# An app a person has let into their account, with every grant it holds
# (generated by maquina:oauth). Not a table: it groups the person's
# unrevoked tokens by client. A token whose hour is up still counts while its
# refresh token works, so "connected" is not the same as "active".
class ConnectedApplication
  attr_reader :user, :client, :tokens

  def self.for(user)
    AccessToken.unrevoked.where(user: user).includes(:oauth_client).group_by(&:oauth_client)
      .map { |client, tokens| new(user: user, client: client, tokens: tokens) }
      .sort_by(&:connected_at)
  end

  # Only among the person's own connections: anyone else's client, or an
  # unknown id, is the same RecordNotFound.
  def self.find(user, client_id)
    self.for(user).find { |application| application.client.id.to_s == client_id.to_s } ||
      raise(ActiveRecord::RecordNotFound)
  end

  def initialize(user:, client:, tokens:)
    @user, @client, @tokens = user, client, tokens
  end

  def to_param
    client.to_param
  end

  def scopes
    tokens.flat_map(&:scopes).uniq.sort_by { |scope| AccessToken::SCOPES.index(scope) || AccessToken::SCOPES.size }
  end

  def last_used_at
    tokens.filter_map(&:last_used_at).max
  end

  def connected_at
    tokens.map(&:created_at).min
  end

  # Every one of the person's tokens for this client stops working at once,
  # and codes it has not exchanged yet are thrown away.
  def revoke!
    AccessToken.transaction do
      AccessToken.unrevoked.where(user: user, oauth_client: client).update_all(revoked_at: Time.current)
      OauthAuthorizationCode.unused.where(user: user, oauth_client: client).delete_all
    end
  end
end
